import { useEffect, useState } from 'react';
import { App as AntApp, Button, Empty, Space, Typography } from 'antd';
import { convApi } from '../api';
import type { Id } from '../api/types';
import { isGroupConv } from '../lib/convType';
import { useChatStore } from '../store/chat';

/** ★ID 比较统一 String 归一（雪花 ID > 2^53，见 api/json.ts）。 */
const sameId = (a: unknown, b: unknown): boolean => a != null && b != null && String(a) === String(b);

/**
 * ★群公告的字数上限：<b>必须与后端 {@code GROUP_NOTICE_MAX_LEN} 逐字相同</b>（1024）。
 *
 * <p>★后端数的是<b>字符数</b>（{@code codePointCount}，一个 emoji 算 1 个），
 * 而 JS 的 {@code str.length} 数的是 UTF-16 单元（一个 emoji 算 2）——
 * 用 {@code length} 当尺子会在含 emoji 的公告上<b>误杀</b>（前端说超了、后端其实收）。
 * 所以这里用 {@code [...str].length}（按码点展开后再数）。
 */
const NOTICE_MAX_LEN = 1024;

/** 按码点数长度（与后端同一把尺子）。 */
const charLen = (s: string): number => [...s].length;

/**
 * 会话窗口顶部「群公告」标签页。
 *
 * <h2>★这一项不是占位，是真功能 —— 后端早就支持，只是前端一直没用</h2>
 *
 * <p>数据来源与写入路径都是现成的：读 {@code ConversationSummaryDto.notice}
 * （会话列表/详情都带），写 {@code PUT /api/instant-message/conversations/{convId}}
 * 的 {@code notice} 字段。所以没有新增任何后端接口。
 *
 * <h2>三条必须由前端体现的服务端语义（写错了界面会骗人）</h2>
 *
 * <ul>
 *   <li><b>只有群主/管理员能改</b>（服务端 {@code requireManager}）。普通成员看到的是
 *       只读的公告 —— ★不能给他一个"编辑"按钮然后让服务端拒绝，那是界面在骗人。</li>
 *   <li><b>单聊没有公告</b>（服务端对单聊直接 {@code PARAM_ERROR}，理由是单聊的名字/资料
 *       都来自对端用户资料，写进库会在对方改昵称后变成旧值）。这里显示一句说明，
 *       而不是一个点了会报错的空框。</li>
 *   <li><b>空串 = 清空，null = 不改</b>。所以保存时永远传<b>字符串</b>
 *       （哪怕是空串），绝不传 undefined —— 传 undefined 等于"不改"，
 *       用户点了保存却什么都没发生。</li>
 * </ul>
 */
export default function ChatAnnouncementPanel({ convId }: { convId: Id | null }) {
  const conv = useChatStore((s) => s.convs.find((c) => sameId(c.convId, convId)));
  const userId = useChatStore((s) => s.userId);
  const loadConversations = useChatStore((s) => s.loadConversations);
  const { message: toast } = AntApp.useApp();

  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState('');
  const [saving, setSaving] = useState(false);

  const notice = conv?.notice ?? '';
  /**
   * ★★DEV-242：团队群（{@code convType=4}）也是群，**公告要照常看得见** ——
   * 写成 {@code === 2} 的话，团队群点进「群公告」得到的是一句
   * "单聊没有群公告"，而平台上明明写着公告。
   *
   * <p>★★DEV-290：团队群的公告**恢复可编辑**（用户 2026-09-24 拍板，逐字：
   * 「与普通群组完全一致:群主/管理员可发布编辑」+「彻底切断:公告不再从空间简介同步
   * (存量不动)」）。DEV-242 当年砍掉 Team 的理由是"改完下次同步就没了"——
   * 现在同步链路里公告字段整个删除（后端 `TeamSpaceSnapshot` 没有 notice、
   * `requireNotSpaceMirror` 闸门只管名称/头像），那个理由**物理上不存在了**。
   * ⇒ {@code canEdit} 与普通群逐字同一形态；服务端闸门已同批放开。
   */
  const isGroup = isGroupConv(conv?.convType);
  // ★角色编码对齐服务端 ImConstants：MEMBER=1 / ADMIN=2 / OWNER=3（DEV-117）。
  const canEdit =
    isGroup && (sameId(conv?.ownerUserId, userId) || conv?.myRole === 2 || conv?.myRole === 3);

  // ★切会话时退出编辑态并丢弃草稿：留着的话，用户在 A 群写了一半的公告
  //   会带着切到 B 群，一按保存就写进了 B 群 —— 这是"数据写到别处"级别的错。
  useEffect(() => {
    setEditing(false);
    setDraft('');
  }, [convId]);

  const onSave = async () => {
    if (convId == null) return;
    setSaving(true);
    try {
      // ★永远传字符串（空串 = 清空公告，见类注释）。
      const changed = await convApi.updateProfile(convId, { notice: draft });
      // ★服务端在"值与当前完全一致"时返回 false 且【不写库】（DEV-39，避免刷新 update_time
      //   污染审计）。这不是失败，但也不能说"已保存"—— 说清楚"没有任何改动"。
      toast.success(changed ? '公告已更新' : '内容没有变化');
      setEditing(false);
      await loadConversations();
    } catch (e) {
      toast.error((e as Error).message);
    } finally {
      setSaving(false);
    }
  };

  const over = charLen(draft) > NOTICE_MAX_LEN;

  return (
    <div className="chat-panel">
      <div className="chat-panel-head">
        <span className="chat-panel-title">群公告</span>
        {canEdit && !editing && (
          <Button size="small" type="primary" onClick={() => { setDraft(notice); setEditing(true); }}>
            {notice ? '编辑' : '新建公告'}
          </Button>
        )}
        {/* ★DEV-290：这里曾经有一段"团队群只读说明"（isTeam ⇒ 渲染
            TEAM_PROFILE_READONLY_HINT 而不给编辑按钮）。拍板「与普通群组完全一致」后删除 ——
            留着它会出现"按钮能点、旁边却写着请到平台修改"的自相矛盾界面。
            ★TEAM_PROFILE_READONLY_HINT 常量本身保留：群设置面板的名称/头像行还在用
            （那两项**仍然**跟随平台）。 */}
      </div>

      <div className="chat-panel-scroll">
        {!isGroup ? (
          /* ★★DEV-193 起这一段<b>不可达</b>了：单聊顶部根本不渲染「群公告」标签，
             连"当前选中页"都会在投影里被弹回「消息」（见 ChatWindow 的 visibleTabs）。
             ★<b>仍然保留</b>它，而且不加任何"如果到不了就删掉"的简化 ——
             它现在是第二道防线：万一哪天有人把投影写错（比如过滤条件反向、
             或者只过滤了标签没过滤 active），用户在这里看到的是**一句人话**，
             而不是一个空白面板。这正是本仓一贯的口径：兜底宁可留着不说话。 */
          <Empty
            image={Empty.PRESENTED_IMAGE_SIMPLE}
            style={{ marginTop: 64 }}
            description="单聊没有群公告（公告是群聊才有的资料）"
          />
        ) : editing ? (
          <>
            <textarea
              className="notice-editor"
              value={draft}
              autoFocus
              placeholder="写点什么给群里的人看…（留空并保存 = 清除公告）"
              onChange={(e) => setDraft(e.target.value)}
            />
            <div className="notice-actions">
              <Typography.Text type={over ? 'danger' : 'secondary'} style={{ fontSize: 12 }}>
                {charLen(draft)} / {NOTICE_MAX_LEN}
                {/* ★超限时把"保存"直接禁掉：让服务端拒绝一次，用户体验上就是
                    "写了 1200 字，点了保存，弹一个红条，字还在" —— 不如当场告诉他。 */}
                {over && '（超出上限，服务端会拒绝）'}
              </Typography.Text>
              <Space>
                <Button size="small" onClick={() => setEditing(false)} disabled={saving}>取消</Button>
                <Button size="small" type="primary" loading={saving} disabled={over} onClick={() => onSave().catch(() => undefined)}>
                  保存
                </Button>
              </Space>
            </div>
          </>
        ) : notice ? (
          // ★公告是纯文本，用 white-space: pre-wrap 保留换行（用户敲的回车要留住），
          //   但**不**渲染成 Markdown/HTML —— 它是群主写给全群看的，
          //   任何富文本都会把它变成一个可注入的面（消息正文那条链路的教训）。
          <div className="notice-body">{notice}</div>
        ) : (
          <Empty
            image={Empty.PRESENTED_IMAGE_SIMPLE}
            style={{ marginTop: 64 }}
            description={canEdit ? '还没有群公告，点右上角「新建公告」写一条' : '群主还没有设置群公告'}
          />
        )}
      </div>
    </div>
  );
}
