import { useCallback, useEffect, useMemo, useRef, useState, type UIEvent } from 'react';
import { Empty, Image, Segmented, Tooltip, Typography } from 'antd';
import { msgApi } from '../api';
import type { Id } from '../api/types';
import { formatSize } from '../api/upload';
import { ATTACHMENT_KINDS } from '../lib/attachment';
import { convFileItemsOf, filterConvFiles, type ConvFileItem, type FileKindFilter } from '../lib/convFiles';
import {
  cacheGet,
  cachePut,
  convFilesKey,
  onConvFilesInvalidated,
  type ConvFilesCacheEntry,
} from '../lib/convFilesCache';
import { saveAndOpenMedia } from '../lib/media';
import { UNKNOWN_NAME, firstNameOf } from '../lib/displayName';
import { IconFile } from './icons';
import PanelCloseButton from './PanelCloseButton';

/** 分类筛选项的显示名（'all' 在最前，其余顺序对齐 ATTACHMENT_KINDS）。 */
const KIND_LABEL: Record<FileKindFilter, string> = {
  all: '全部',
  image: '图片',
  file: '文件',
  video: '视频',
  audio: '音频',
};

/** 两位补零。 */
const pad2 = (n: number): string => String(n).padStart(2, '0');

/**
 * 文件时间（照聊天里时间分割线的口径，但带上年份）：
 * 今天「今天 HH:mm」、昨天「昨天 HH:mm」、更早「YYYY/M/D HH:mm」。
 *
 * <p>★文件面板不像聊天那样有"上下文时间线"，一条光秃秃的 `14:32` 无法判断是哪天的。
 */
function fileTime(ms?: number): string {
  if (!ms) return '';
  const d = new Date(ms);
  const hm = `${pad2(d.getHours())}:${pad2(d.getMinutes())}`;
  const today = new Date();
  if (d.toDateString() === today.toDateString()) return `今天 ${hm}`;
  if (d.toDateString() === new Date(today.getTime() - 86_400_000).toDateString()) return `昨天 ${hm}`;
  return `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()} ${hm}`;
}

// ================================================================ 服务端分页 + 模块级缓存（DEV-300）

/** 每页拉多少条<b>原始消息</b>（服务端 clamp 到 [20,100]；附件行可能多于消息数）。 */
const PAGE_SIZE = 20;

/**
 * ★空页自动续拉的保险丝。
 *
 * <p>「空页 + hasMore=true」是<b>合法</b>形态（一整页原始消息全被撤回/清空过滤掉，
 * 见 {@code msgApi.files} 的契约注释），所以拿到空页不能停，必须续拉 —— 但续拉
 * 必须有上限，否则一个游标不推进的服务端 bug 会把浏览器变成请求泵。
 * ★50 页 = 至少 1000 条原始消息里一个附件都没有才会触顶；触顶后<b>如实告知</b>
 * 并留「继续查找」入口（不许静默装作"翻完了"——那是拿假完整骗用户）。
 */
const MAX_AUTO_PAGES = 50;

/* ★★第 7 条反馈（2026-10-08）：模块级缓存与"什么时候作废"搬到了
   `lib/convFilesCache.ts` —— 搬出去的原因是**作废的动作发生在 store 里**
   （发送成功 / 撤回 / 删除四条动作都在 `store/chat.ts`），而组件文件不该被 store
   import（反向依赖）。那个模块同时是失效总线：`invalidateConvFiles(convId)` 先删
   缓存再广播，本组件订阅后当场重拉一次（见下面的 refreshTick）。
   缓存本身仍是模块级单例，所以"面板关了再开秒出"这条行为一个字没变。 */

/**
 * 会话窗口顶部「文件」标签页：本会话<b>全部</b>消息里的附件（DEV-300 起走服务端）。
 *
 * <h2>★DEV-300：从「已加载消息的窗口」改成「服务端全量 + 滚动翻页」</h2>
 *
 * <p>此前这里聚合的是 store 里<b>已加载的消息</b>（进会话时一屏 + 上翻过的部分），
 * 用户找很早的文件会以为"文件丢了"。现在数据来自
 * {@code GET …/conversations/{id}/files}（服务端按 msg_type 过滤 + seq DESC 分页），
 * 首屏秒出、滚到底部自动翻更早的页。★顺序是服务端给的<b>新→旧</b>，前端不得反转。
 *
 * <h2>缓存与"新发的文件"</h2>
 *
 * <p>模块级 {@link convFilesCache} 让重开面板秒出；但缓存会旧 —— 所以<b>每次打开
 * 都照常拉一遍首页</b>：命中缓存时先渲染缓存、首页回来后把新出现的文件按 key
 * （{@code msgId#index}）去重后插到最前。游标与 hasMore <b>沿用缓存的</b>：
 * 新首页只覆盖最新一段，若采用它的游标，续翻会把缓存已翻过的页整段重翻。
 *
 * <h2>安全</h2>
 *
 * <p>每一项的 {@code url} 来自 {@link convFileItemsOf}，那里已经逐个过了
 * {@code safeMediaUrl}（不合法的不入列；服务端透传 ≠ 可信，DEV-293①）。
 * 这里直接用在 {@code href} / {@code src} 上是安全的 —— 但★<b>不要</b>在这里再拼
 * 任何字符串（比如自己加 query 参数），那会让"过滤发生在别处"这个前提失效。
 */
export default function ChatFilesPanel({ convId, onClose }: { convId: Id | null; onClose?: () => void }) {
  const [filter, setFilter] = useState<FileKindFilter>('all');
  const [files, setFiles] = useState<ConvFileItem[]>([]);
  const [hasMore, setHasMore] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  /** 空页续拉触顶（MAX_AUTO_PAGES）且仍 hasMore：如实提示并给「继续查找」。 */
  const [autoStopped, setAutoStopped] = useState(false);

  /** 缓存键（String 归一）。★与 lib/convFilesCache 用**同一个**换算函数，不各写一遍。 */
  const key = convFilesKey(convId);

  // ★refs 是"翻页循环"的真相源（state 有闭包陈旧问题，循环里读 state 会拿到旧值）。
  const itemsRef = useRef<ConvFileItem[]>([]);
  const cursorRef = useRef<string | undefined>(undefined);
  const hasMoreRef = useRef(false);
  const inflightRef = useRef(false);
  /** 当前面板正在服务的会话 key：迟到的响应靠它判"还要不要"。 */
  const activeKeyRef = useRef<string | null>(null);

  const applyEntry = useCallback((e: ConvFilesCacheEntry) => {
    itemsRef.current = e.items;
    cursorRef.current = e.nextCursor;
    hasMoreRef.current = e.hasMore;
    setFiles(e.items);
    setHasMore(e.hasMore);
  }, []);

  /**
   * 从当前游标往更早翻，直到拿到非空一页 / 翻完 / 触 {@link MAX_AUTO_PAGES} 保险丝。
   *
   * <p>也兼任「重试」：首屏失败时游标还是 undefined，重试等价于重拉首页。
   */
  const loadOlder = useCallback(
    async (forKey: string) => {
      if (inflightRef.current || !hasMoreRef.current) return;
      inflightRef.current = true;
      setLoading(true);
      setError(null);
      setAutoStopped(false);
      let pages = 0;
      try {
        while (pages < MAX_AUTO_PAGES) {
          pages += 1;
          const page = await msgApi.files(forKey, cursorRef.current, PAGE_SIZE);
          // ★切会话/关面板后迟到的响应：缓存照写（数据本身是对的、按 key 隔离），
          //   但绝不许写进当前面板的 state —— 跨会话串列表比不显示更坏。
          const stillActive = activeKeyRef.current === forKey;
          const fresh = convFileItemsOf(page.records);
          const base = cacheGet(forKey)?.items ?? (stillActive ? itemsRef.current : []);
          const seen = new Set(base.map((i) => i.key));
          const entry: ConvFilesCacheEntry = {
            items: [...base, ...fresh.filter((i) => !seen.has(i.key))],
            nextCursor: page.nextCursor,
            hasMore: page.hasMore,
          };
          cachePut(forKey, entry);
          if (stillActive) applyEntry(entry);
          if (fresh.length > 0 || !page.hasMore) break;
          // ★空页 + hasMore：合法形态（整页被撤回/清空），自动续拉。
        }
        if (activeKeyRef.current === forKey) {
          setLoading(false);
          if (pages >= MAX_AUTO_PAGES && hasMoreRef.current) setAutoStopped(true);
        }
      } catch {
        if (activeKeyRef.current === forKey) {
          setLoading(false);
          setError('加载更早的文件失败');
        }
      } finally {
        inflightRef.current = false;
      }
    },
    [applyEntry],
  );

  /**
   * ★★第 7 条反馈（用户原话「上传或撤回群文件后，右侧「文件」列表不实时同步
   * （面板正开着时不变，重开面板才更新）」）：本端"动了附件"（发送成功 / 撤回 /
   * 删除消息）时，正开着的这个面板**当场做一次"重开面板"**（见下面 effect 的依赖）。
   *
   * <p>★判据只比 key：失效是**按会话**广播的（`lib/convFilesCache` 那一层按 convId 删缓存），
   * 别的会话发文件不该刷新这里。
   * ★读 {@code activeKeyRef} 而不是 {@code key}：本订阅只挂一次（依赖 []），
   * 闭包里的 key 会永远停在挂载时那个会话上 —— 切过会话之后就判错了。
   * ★ref 的写入在主 effect 的第一行（切会话先于任何失效事件发生）。
   */
  const [refreshTick, setRefreshTick] = useState(0);
  useEffect(
    () =>
      onConvFilesInvalidated((invalidated) => {
        if (invalidated === activeKeyRef.current) setRefreshTick((t) => t + 1);
      }),
    [],
  );

  // 打开面板 / 切会话 / ★收到失效通知：缓存秒出 + 拉新首页合并（见类注释「缓存与新发的文件」）。
  // ★★`refreshTick` 进依赖 = 失效时把这段 effect **整个重跑一遍** ——
  //   而失效那一侧已经把缓存删了 ⇒ 这里走的是"无缓存"分支：清空列表、拉全新首页、
  //   游标重置。这正是"重开面板"的等价物，也正是我们要的语义（见 lib/convFilesCache 文件头：
  //   "插入好写、删除没依据"，只有重拉能把撤回掉的那条真正去掉）。
  //   ★代价：用户翻过的老页会回到第一页（列表滚回顶部）—— 但触发者是用户自己
  //   "刚发了/刚撤回了"，界面刷新是符合预期的；不做"就地插一条"是刻意的，理由见文件头。
  useEffect(() => {
    activeKeyRef.current = key;
    if (key == null) {
      applyEntry({ items: [], nextCursor: undefined, hasMore: false });
      setLoading(false);
      setError(null);
      return;
    }
    let cancelled = false;
    const cached = cacheGet(key);
    // ★无缓存时 hasMore 先给 true：首屏失败后「重试」走 loadOlder，它靠这个放行。
    applyEntry(cached ?? { items: [], nextCursor: undefined, hasMore: true });
    setError(null);
    setAutoStopped(false);
    if (!cached) setLoading(true);
    (async () => {
      try {
        const page = await msgApi.files(key, undefined, PAGE_SIZE);
        if (cancelled) return;
        const fresh = convFileItemsOf(page.records);
        const cur = cacheGet(key);
        const entry: ConvFilesCacheEntry = cur
          ? {
              // 命中缓存：新首页里没见过的插到最前（新→旧不破序），游标/hasMore 沿用缓存。
              items: [
                ...fresh.filter((i) => !cur.items.some((c) => c.key === i.key)),
                ...cur.items,
              ],
              nextCursor: cur.nextCursor,
              hasMore: cur.hasMore,
            }
          : { items: fresh, nextCursor: page.nextCursor, hasMore: page.hasMore };
        cachePut(key, entry);
        applyEntry(entry);
        setLoading(false);
        // 首屏就是空页 + hasMore（合法形态）：自动续拉，别让用户对着空面板。
        if (!cached && entry.items.length === 0 && entry.hasMore) void loadOlder(key);
      } catch {
        if (!cancelled) {
          setLoading(false);
          setError(cached ? '刷新最新文件失败（下面仍显示上次加载的结果）' : '文件列表加载失败');
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [key, refreshTick, applyEntry, loadOlder]);

  /** 滚到底部附近就翻下一页（阈 48px：等"到底了"再翻，列表会先跳一下才动）。 */
  const onScroll = useCallback(
    (e: UIEvent<HTMLDivElement>) => {
      const el = e.currentTarget;
      if (el.scrollHeight - el.scrollTop - el.clientHeight < 48 && key != null) {
        void loadOlder(key);
      }
    },
    [key, loadOlder],
  );

  const shown = useMemo(() => filterConvFiles(files, filter), [files, filter]);

  return (
    <div className="chat-panel">
      <div className="chat-panel-head">
        <span className="chat-panel-title">文件{files.length > 0 ? ` · ${files.length} 个` : ''}</span>
        {/* ★DEV-253：右缘那一组。★DEV-254 需求②之后这一组里**只剩「×」**了
            （筛选器被移到了下面单独一行，原因见那个 `.chat-panel-filter` 上的注释）。
          ★保留这层组容器而不是把 button 直接挂到 head 上：六个面板的头部结构必须同构，
            否则"× 在最右"这条几何判据会在本面板上退化成另一套布局（这正是本批要修的毛病）。 */}
        <div className="chat-panel-head-end">
          {onClose && <PanelCloseButton onClose={onClose} panel="文件" />}
        </div>
      </div>

      {/* ★★DEV-254 需求②（用户原话「文件的侧边栏"x"的位置不对」）：
          筛选器原来和「×」一起挂在 `.chat-panel-head` 的右缘那一组里。
          实测（320px 侧栏、可用宽 288px，见探针读数）：
            标题「文件」26.5 + gap 12 + 右缘组 258.8 = 297.3 > 288 ⇒ head **折成两行**，
            于是「×」被挤到**第二行**，而其余五个面板的「×」都在第一行 —— 这就是"位置不对"。
          ★为什么不把 head 改成 nowrap：那样标题会被 ellipsis 裁掉（DEV-253 的 H9 正是钉这个），
            而「×」是这条侧栏唯一的出口，不许被裁也不许被挤走。
          ★为什么不继续缩筛选器：四项「全部/图片/文件/视频/音频」是中文固定宽，
            再缩就要换行或截字，代价比"多占一行"大得多。
          ★所以选**换行**：筛选是"看完标题之后才用"的东西，天然属于第二行。 */}
      <div className="chat-panel-filter">
        <Segmented
          size="small"
          value={filter}
          onChange={(v) => setFilter(v as FileKindFilter)}
          options={(['all', ...ATTACHMENT_KINDS] as FileKindFilter[]).map((k) => ({
            value: k,
            label: KIND_LABEL[k],
          }))}
        />
      </div>

      {/* ★DEV-300：说明行改全量语义。此前它必须坦白"只显示已加载的"，
          现在数据是服务端按会话检索的 —— 但"往下滚才翻更早"这件事仍要说，
          否则用户在一屏结果里找不到老文件时，还是会以为"丢了"。 */}
      <div className="chat-panel-hint">
        列出本会话<b>全部</b>消息里的附件，最新的在最前；往下滚动会自动加载更早的文件。
      </div>

      <div className="chat-panel-scroll" onScroll={onScroll}>
        {shown.length === 0 && !loading && !error ? (
          <Empty
            style={{ marginTop: 48 }}
            description={
              files.length === 0
                ? '这个会话里还没有文件'
                : `没有「${KIND_LABEL[filter]}」类型的文件（已加载 ${files.length} 个附件）`
            }
          />
        ) : (
          <ul className="file-list">
            {shown.map((it) => (
              <FileRow key={it.key} it={it} />
            ))}
          </ul>
        )}
        {/* ★底部状态行一律复用 .chat-panel-hint（不新增 CSS 类）：
            提示就是提示，长得该一样。 */}
        {loading && (
          <div className="chat-panel-hint">
            {files.length === 0 ? '正在加载文件…' : '正在加载更早的文件…'}
          </div>
        )}
        {error && !loading && (
          <div className="chat-panel-hint">
            {error}
            <Typography.Link onClick={() => key != null && void loadOlder(key)}>点击重试</Typography.Link>
          </div>
        )}
        {autoStopped && !loading && !error && (
          <div className="chat-panel-hint">
            已自动翻过 {MAX_AUTO_PAGES} 页还没找到文件，更早的消息里可能还有。
            <Typography.Link onClick={() => key != null && void loadOlder(key)}>继续查找</Typography.Link>
          </div>
        )}
        {!hasMore && !loading && !error && files.length > 0 && (
          <div className="chat-panel-hint">已经到了最早的文件。</div>
        )}
      </div>
    </div>
  );
}

/** 一行文件。图片给缩略图（可点开大图），其余给类型图标。 */
function FileRow({ it }: { it: ConvFileItem }) {
  // ★DEV-202 #218：兜底由 `用户{senderId}` 改成「未知用户」—— id 不上界面。
  //   ★这一支拿不到「（用户名）」：`ConvFileItem` 只有一个 senderName 快照字段。
  const who = firstNameOf(UNKNOWN_NAME, it.senderName);
  return (
    <li className="file-row">
      {it.kind === 'image' ? (
        // ★宽高固定 + objectFit：不固定的话整行会随图片原始尺寸跳动，
        //   列表里几十张图会让滚动位置一直抖。
        <Image className="file-thumb" src={it.url} width={40} height={40} style={{ objectFit: 'cover' }} />
      ) : (
        // 走到这里 kind 一定不是 image（上面的分支已经接走了），所以只可能是文件类图标。
        <span className={`file-thumb file-thumb-${it.kind}`}>
          <IconFile size={18} />
        </span>
      )}
      <div className="file-meta">
        {/* ★title 给全名：长文件名会被 CSS 截断，截断后必须还能看全。 */}
        <Tooltip title={it.fileName}>
          {/* ★★DEV-218：下面两处 download 名都走 downloadNameOf —— 它与气泡里的
              下载入口**算出同一个文件名**（同一个文件从两个入口存下来却叫两个名字，
              用户会以为下到了两个文件）。它同时管两件事：把发送方路径里的 `/` 压平
              （带分隔符时浏览器会**静默忽略** download），以及给没后缀的名字从 URL 借一个。
              ★★DEV-268 第 1 条：可视类（图片/视频/语音）**接管**这一下点击，与下面「下载」
              那个按钮走同一个入口（既开新窗口、又落盘）。在此之前两处是分裂的：
              这一行挂着 `download` ⇒ 同源**只存盘、不开窗**，与用户要的"在新窗口打开并下载"
              正好差一半 —— 而用户看到的又是同一行文字，很自然会当成"下载按钮没修好"。
              ★★DEV-270 第 2 条：文档类原来**不接管**（{@code isViewableKind} 为假直接 return），
              理由是"`<a download>` 对同源的 pdf 本来就生效"——**这个前提是错的**：
              平台的附件地址一律 302 到跨源，带上 download 的链接点一下会把**当前页**
              导航走（详见 lib/media.ts 的 openAnchorNewTab）。所以 download 整个删掉、
              所有类型一律接管。 */}
          <a
            className="file-name"
            href={it.url}
            target="_blank"
            rel="noopener noreferrer"
            onClick={(e) => {
              e.preventDefault();
              void saveAndOpenMedia({ kind: it.kind, url: it.url, fileName: it.fileName }).catch(
                () => undefined,
              );
            }}
          >
            {it.fileName}
          </a>
        </Tooltip>
        <span className="file-sub">
          {who} · {fileTime(it.sendTime)}
          {/* ★size=0 表示"未知"，显示「—」而不是「0 B」——0 B 会被当成文件是空的。 */}
          {` · ${it.size > 0 ? formatSize(it.size) : '—'}`}
        </span>
      </div>
      {/* ★★DEV-226 需求②（用户原话「视频语音等下载还是在当前窗口打开了，
          需要在新窗口打开并下载」）：这一下**不再交给 `<a download>`**，
          改成 {@link saveAndOpenMedia} —— 它把字节取回来、开一个新窗口给用户看、
          同时在本地存一份（为什么必须这样做、代价是什么，全写在那个函数的注释里）。
          ★`href` / `target` / `rel` **刻意保留**：它们不再是主路径，而是
            ①键盘可达与"链接"的语义（去掉 href 的 <a> 不可聚焦）；
            ②中键/⌘+点击时浏览器走原生行为，仍能拿到文件。
          ★onClick 里 preventDefault 掉左键那一次原生导航 —— 不 prevent 的话
            这一下会既走原生下载又走我们这一套，用户拿到两份。 */}
      <Typography.Link
        className="file-dl"
        href={it.url}
        target="_blank"
        rel="noopener noreferrer"
        /* ★★DEV-270 第 2 条：`download` 删掉（与上面那处同因，见 lib/media.ts
           的 openAnchorNewTab）。落盘已由 onClick 里的 saveAndOpenMedia 负责。 */
        onClick={(e) => {
          e.preventDefault();
          void saveAndOpenMedia({ kind: it.kind, url: it.url, fileName: it.fileName }).catch(
            () => undefined,
          );
        }}
      >
        下载
      </Typography.Link>
    </li>
  );
}
