import { useRef } from 'react';
import { App as AntApp, Button, Input, Modal, Typography } from 'antd';
import { QRCodeCanvas } from 'qrcode.react';
import { copyText } from '../lib/clipboard';
import {
  currentInviteUrl,
  INVITE_COPIED_TEXT,
  INVITE_COPY_FAILED_TEXT,
  INVITE_QR_DESC,
  INVITE_QR_TITLE,
  INVITE_URL_UNAVAILABLE_TEXT,
  inviteFileName,
} from '../lib/groupInvite';

/**
 * ★★DEV-356：群二维码 + 邀请链接弹窗（入口在群设置面板的「群号」那一行下面）。
 *
 * <h2>★★二维码里放的**就是**那条邀请链接（不是裸群号）</h2>
 *
 * <p>用户的两条需求（"生成群二维码" / "生成群邀请链接"）共用<b>同一份内容</b>：
 * 扫出来直接是一条能点开的链接，点开就进 IM 并弹「申请加入」确认框。
 * ★两条路各放各的东西（比如码里放裸群号、链接里放 URL）会带来一个必然会发生的分叉：
 * 扫出来的码只能进「按群号加入」的手填弹窗，而链接点开是自动预填 ——
 * 同一个群、两种体验，用户以为其中一个坏了。
 *
 * <h2>★★三条与"扫得出来"直接相关的取舍</h2>
 *
 * <ul>
 *   <li><b>{@code level="M"}</b>（纠错级别）：链接比裸群号长得多，
 *       级别越高码越密、越难扫；M 是"能被污损 15% 仍可读"与"码不至于太密"的常用折中。</li>
 *   <li><b>{@code marginSize={4}}</b>：库的默认是 <b>0</b>（二维码贴到画布边缘）。
 *       ★实测里这不是小事：多数手机扫码器要求四周有一圈静默区，
 *       贴边的图在屏幕上还能扫，<b>截图/打印之后就扫不出来</b>了。</li>
 *   <li><b>画布按 640px 画、按 220px 显示</b>：{@code size} 决定的是"画多少像素"。
 *       直接按 220 画，用户下载/打印出来只有 220px，放大就糊 ——
 *       而 <b>这条链接是要被发给别人的</b>，大概率会被截图转发、甚至打印贴出来。
 *       ★用 CSS 把它显示小只是"看起来小"，像素一个没少。</li>
 * </ul>
 *
 * <h2>★★颜色不跟随主题</h2>
 *
 * <p>前景黑、背景白是<b>写死</b>的。跟随暗色主题（白码黑底）会让一部分扫码器
 * 直接识别失败 —— 而失败发生在<b>别人的手机</b>上，我们这边看不到任何异常。
 *
 * <h2>★复制走 lib/clipboard 而不是 antd 的 copyable</h2>
 *
 * <p>101 是<b>明文 http 的域名</b>，那里 {@code navigator.clipboard} 根本不存在；
 * {@code copyText} 自带 {@code execCommand('copy')} 回落（见那个文件的文件头）。
 * antd 的 {@code Typography.Text copyable} 用的是它自己那条路，在这个环境下
 * 点了会<b>静默什么都不发生</b>（用户粘贴出来还是上一次的内容）。
 */
export default function GroupInviteModal({
  open,
  groupNo,
  onClose,
}: {
  open: boolean;
  /** ★群号（字符串，雪花值 —— 见 lib/joinGroup 的 normalizeGroupNo）。null ⇒ 本弹窗不该被打开。 */
  groupNo: string | null;
  onClose: () => void;
}) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const { message: toast } = AntApp.useApp();

  /**
   * ★每次渲染现算（而不是存进 state / useMemo）：
   * {@code currentInviteUrl} 读的是 {@code window.location}，纯函数、无副作用，
   * 算一次的成本可以忽略；★存进 state 反而要处理"域名变了但 state 没跟着变"
   * （那在测试环境里换 host 时会静默生成一条指向上一个 host 的链接）。
   * ★拿不到 origin（或群号非法）⇒ null ⇒ 走下面那条"生成不了"的分支，
   * <b>绝不</b>降级成相对路径或空串。
   */
  const url = currentInviteUrl(groupNo);
  const fileName = inviteFileName(groupNo);

  const onCopy = async () => {
    if (!url) return;
    const ok = await copyText(url);
    // ★按返回值提示（不是"点了就说成功"）：失败时用户粘贴出旧内容，
    //   会以为是自己点错了 —— 而真话是"这个环境复制不了，请手动选中"。
    if (ok) toast.success(INVITE_COPIED_TEXT);
    else toast.error(INVITE_COPY_FAILED_TEXT);
  };

  /**
   * ★下载二维码：直接取画布的 {@code toDataURL}。
   *
   * <p>★为什么不是"在服务端生成一张图"或者"用 html2canvas 截图"：
   * 画布就在眼前，{@code toDataURL} 是同步的、离屏的、不依赖任何网络
   * —— 这也是拍板选 {@code frontend} 的直接好处（后端零改动、零新接口）。
   *
   * <p>★走一个临时 {@code <a download>} 落盘（与附件下载同一套做法）：
   * 这里<b>只</b>落盘、<b>不</b>预开新窗口 —— DEV-341 那次"点一次落两份"
   * 的根因就是"对所有类型都既开窗又落盘"。
   */
  const onDownload = () => {
    const canvas = canvasRef.current;
    if (!canvas) {
      // ★理论上到不了（画布在 open 时就渲染了），但**不静默**：
      //   真要发生，用户点一下没反应会以为按钮坏了。
      toast.error('二维码还没准备好，请稍后再试');
      return;
    }
    const a = document.createElement('a');
    a.href = canvas.toDataURL('image/png');
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  return (
    <Modal
      title={INVITE_QR_TITLE}
      open={open}
      onCancel={onClose}
      footer={(
        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
          <Button onClick={onClose}>关闭</Button>
          <Button disabled={!url} onClick={() => onCopy().catch(() => undefined)}>
            复制链接
          </Button>
          <Button type="primary" disabled={!url} onClick={onDownload}>
            下载二维码
          </Button>
        </div>
      )}
      width={360}
    >
      {url ? (
        <>
          <div style={{ display: 'flex', justifyContent: 'center', padding: '4px 0 12px' }}>
            <QRCodeCanvas
              ref={canvasRef}
              value={url}
              size={640}
              // ★显示小、像素大（理由见类注释第 3 条）。
              style={{ width: 220, height: 220 }}
              level="M"
              // ★静默区：不写这个默认是 0（贴边），打印/截图后扫不出来。
              marginSize={4}
              // ★写死的黑白（理由见类注释"颜色不跟随主题"）。
              bgColor="#FFFFFF"
              fgColor="#000000"
              // ★无障碍：读屏软件与"图片加载失败"时都能知道这是什么。
              title={INVITE_QR_TITLE}
            />
          </div>
          <Typography.Paragraph type="secondary" style={{ fontSize: 12 }}>
            {INVITE_QR_DESC}
          </Typography.Paragraph>
          <Input value={url} readOnly onFocus={(e) => e.target.select()} />
        </>
      ) : (
        // ★★"生成不了"必须说出来：这一行只在拿不到页面地址（或群号非法）时出现，
        //   默默显示一个空框会让用户以为是加载慢。
        <Typography.Paragraph type="secondary" style={{ fontSize: 12 }}>
          {INVITE_URL_UNAVAILABLE_TEXT}
        </Typography.Paragraph>
      )}
    </Modal>
  );
}
