import { useEffect, useState } from 'react';
import { App as AntApp, Input, Modal, Space, Tabs, Typography } from 'antd';
import type { AgentSearchItem, IdInput } from '../api/types';
// ★★DEV-262：「搜到人 → 发消息」这里也要动态判一次（用户的字面要求）。
import { talkGateOf } from '../lib/canTalk';
import { CONTACT_STATUS, SUBJECT_TYPE } from '../lib/contact';
import { useChatStore } from '../store/chat';
import AgentSearchSelect from './AgentSearchSelect';
import UserSearchSelect from './UserSearchSelect';

/**
 * ★「添加伙伴」——原型图右上角 {@code +} 菜单的第二项。
 *
 * <h2>★★一个弹窗，两个<b>语义完全不同</b>的动作</h2>
 *
 * <p>「智联录」方案确认时用户选了"真好友关系（加人要申请/同意）"，
 * 同时又要求「添加伙伴」能"搜平台用户 → 直接发起单聊"。这两件事在数据上不是一回事，
 * 但在用户脑子里是同一个念头（"我要跟这个人说话"），所以放在同一个弹窗里，
 * 用两个按钮把差别摆到明面上：
 *
 * <table border="1">
 *   <caption>两个按钮各自做的事</caption>
 *   <tr><th></th><th>服务端动作</th><th>对方的通讯录</th><th>结果</th></tr>
 *   <tr><td><b>发消息</b>（主）</td>
 *       <td>建/开单聊 + {@code POST /contacts {direct:true}}</td>
 *       <td>★<b>完全不变</b>（对方甚至不知道）</td><td>立刻能聊，对方出现在我的智联录里</td></tr>
 *   <tr><td><b>加为联系人</b>（次）</td>
 *       <td>{@code POST /contacts}（不传 direct）</td>
 *       <td>★出现一条<b>待他同意</b>的申请</td><td>对方同意后双方互为联系人</td></tr>
 * </table>
 *
 * <p>★★为什么"发消息"不顺手也写对方那一行：那等于<b>单方面把别人加进我的通讯录还倒过来</b>
 * ——用户给谁发条消息，谁的通讯录里就凭空多出一个人，而对方从没同意过任何事。
 * 服务端 {@code addDirect} 只写一行正是为此（E2E 用例⑥专门锁死这条）。
 *
 * <h2>★两个按钮的视觉主次是刻意的</h2>
 *
 * <p>「发消息」是主按钮：绝大多数人点「添加伙伴」的真实目的是**说上话**，
 * 而不是维护一份联系人名单。把「加为联系人」做成主按钮会诱导用户走一条
 * "发不出消息、还要等对方同意"的路。
 *
 * <h2>★★「用户 / 智能体」两个 Tab（二期）</h2>
 *
 * <p>★DEV-258：第一个 Tab 的文案由「人」改成「用户」（见下面 {@code items} 那处注释）。
 *
 * <p>搜人走 {@code GET /search/contacts}，搜智能体走
 * {@code GET /contacts/agents}（平台内网 {@code agent/search}）——
 * 两个数据源、两套可见范围规则，所以是两个 Tab 而不是一个下拉。
 *
 * <p>★★但<b>搜到之后完全同路</b>：智能体搜索结果里的 {@code userId} 是服务端
 * **编码好的 subject id**，与真人一样直接塞进 {@code POST /contacts}。
 * <b>零新增字段、零额外接口</b> —— 这是服务端 {@code AgentSearchItem} 沿用
 * {@code userId} 这个字段名的全部用意（见该 DTO 的注释）。
 *
 * <p>★★唯一<b>文案上</b>必须分开的地方：「加为联系人」对智能体是**立刻生效**的
 * （服务端对智能体强制直连 —— 它永远不会点"同意"，走申请就是把自己挂死）。
 * 若沿用"对方同意后互为联系人"那句话，用户会去等一个永远不会来的同意。
 */
export default function AddPartnerModal({
  open,
  onClose,
  onDone,
}: {
  open: boolean;
  onClose: () => void;
  /**
   * ★「发消息」成功后回调（带上刚打开/命中的 convId）。
   * ChatPage 用它切回「消息」Tab —— 不切的话用户会停在智联录，
   * 看着"什么都没发生"，而会话其实已经开好了。
   */
  onDone?: (convId: string) => void;
}) {
  const userId = useChatStore((s) => s.userId);
  const addContact = useChatStore((s) => s.addContact);
  const startChatWith = useChatStore((s) => s.startChatWith);
  const canTalkMap = useChatStore((s) => s.canTalkMap);
  const loadCanTalk = useChatStore((s) => s.loadCanTalk);
  const { message: toast } = AntApp.useApp();

  /**
   * ★当前 Tab：{@code 'user'}（人）/ {@code 'agent'}（智能体）。
   *
   * <p>★★两个 Tab 只改变<b>怎么搜</b>，不改变<b>搜到之后干什么</b> ——
   * 这正是二期接入 {@code agent/search} 之后的形态：智能体搜索结果里的
   * {@code userId} 是服务端编码好的 subject id，与真人走同一个
   * {@code POST /contacts}。若哪天有人给智能体加了"专用提交路径"，
   * 那个分支就是多余的（而多余的分支迟早会与主路径不一致）。
   */
  const [tab, setTab] = useState<'user' | 'agent'>('user');

  /** 选中的目标（两个模式都来自远程搜索，见 {@link UserSearchSelect}）。 */
  const [target, setTarget] = useState<IdInput | null>(null);
  /**
   * ★选中项是不是智能体。
   *
   * <p>★它**只用来显示**（角标 / 提示语），**不参与**提交决策 ——
   * 服务端会自己按段位判定（{@code ContactAddResult.subjectType}），
   * 前端按它分叉提交就等于把"谁是智能体"的判定权抢过来一半。
   */
  const [targetIsAgent, setTargetIsAgent] = useState(false);
  /** 申请附言（只有「加为联系人」会用到；「发消息」不传它）。 */
  const [applyMsg, setApplyMsg] = useState('');
  const [loading, setLoading] = useState<'' | 'chat' | 'contact'>('');

  /**
   * ★★DEV-226 需求⑨：**这一栏是不是"智能体语境"** —— 判据是"当前在智能体 Tab
   * 或者选中的就是智能体"，也就是 `tab === 'agent' || targetIsAgent`。
   *
   * <p>★为什么不能用 `targetIsAgent` 一个量：它只在**选中之后**才为真，
   * 而在智能体 Tab 上"还没选人"是用户看到的**第一眼**状态 ——
   * 那一刻附言框仍然在，用户原话「添加智能体不需要申请附言」说的就是这一眼。
   *
   * <p>★它同时决定提示语与**提交时要不要带附言**（见 {@link onApplyContact}）：
   * 框都藏起来了却还把上一次在「用户」Tab 里打的附言发出去，
   * 就是"界面上看不见、后台却发了"的那类事故。
   */
  const agentMode = tab === 'agent' || targetIsAgent;

  /**
   * ★★DEV-262：选中的这个人**能不能直接发消息**（服务端判：是我的联系人 <b>或</b> 同 Team）。
   *
   * <p>用户原话：「只要不是联系人一律拒发……包括<b>页面上搜到人也要动态判断是否展示
   * 发消息按钮</b>」—— 这里就是"搜到人"那一处。
   *
   * <p>★★三态：{@code 'unknown'}（还没问出结果）**不拦**、只有 {@code 'no'} 才拦。
   * 混起来会让按钮在"刚选中、请求还在飞"的那一瞬间闪一下禁用态。
   */
  const gate = target == null ? 'unknown' : talkGateOf(canTalkMap, target);

  // ★选中谁就问谁。★幂等（已经问过的不会再发请求），且换人时旧的答案还在 map 里、各归各的。
  useEffect(() => {
    if (target == null) return;
    void loadCanTalk([target]);
  }, [target, loadCanTalk]);

  const reset = () => {
    setTarget(null);
    setTargetIsAgent(false);
    setApplyMsg('');
    setLoading('');
  };

  /** ★切 Tab 必须清掉已选中的目标：两个 Tab 的候选集完全不重叠，留着会"选着 A 提交 B"。 */
  const switchTab = (k: string) => {
    setTab(k === 'agent' ? 'agent' : 'user');
    setTarget(null);
    setTargetIsAgent(false);
  };

  const close = () => {
    reset();
    onClose();
  };

  /**
   * ★「发消息」：建/开单聊 + 把对方落到我这边（对方通讯录不动）。
   *
   * ★★DEV-373：成功时【刻意不弹 toast】（用户 2026-10-10：「不用提示"已发起会话"」）。
   *   与 `UserCard.onSend` 是同一个动作、**同批同口径**：弹窗关闭 + 外层 `openConv` 切过去
   *   ⇒ 界面本身就是回执。★失败**照旧弹**；★「未选目标」的 warning 也照旧（那是拦截，不是回执）。
   */
  const onSendChat = async () => {
    if (target == null) {
      toast.warning('请先选择要添加的伙伴');
      return;
    }
    setLoading('chat');
    try {
      const convId = await startChatWith(target);
      // ★先 reset 再回调：回调里会切 Tab 并 await selectConv，
      //   期间弹窗还挂着的话，用户会看到"已经打开的会话"背后还压着一个弹窗。
      reset();
      onClose();
      onDone?.(convId);
    } catch (e) {
      toast.error((e as Error).message || '发起会话失败');
    } finally {
      setLoading('');
    }
  };

  /** ★「加为联系人」：走申请/同意链路。三种结果的文案完全不同（见下面的分支）。 */
  const onApplyContact = async () => {
    if (target == null) {
      toast.warning('请先选择要添加的伙伴');
      return;
    }
    setLoading('contact');
    try {
      // ★DEV-226 需求⑨：智能体语境下**不带附言**（附言框那时是藏起来的，
      //   不能再把「用户」Tab 里打过的字发出去 —— 见 agentMode 的注释）。
      const r = await addContact(target, { message: agentMode ? undefined : applyMsg.trim() || undefined });
      if (r.alreadyContact) {
        // ★必须与"刚添加成功"区分：后者会让用户以为刚刚发生了一次添加，其实什么都没做
        toast.info('他已经在你的联系人里了');
      } else if (r.status === CONTACT_STATUS.PENDING_OUT) {
        toast.success('申请已发出，等待对方同意');
      } else {
        toast.success('已添加为联系人');
      }
      reset();
      onClose();
    } catch (e) {
      toast.error((e as Error).message || '添加失败');
    } finally {
      setLoading('');
    }
  };

  return (
    <Modal
      title="添加伙伴"
      open={open}
      onCancel={close}
      destroyOnClose
      // ★不用 onOk/okText：底部是**两个平等但主次分明**的动作，
      //   塞进 antd 的"确定/取消"会把"发消息"和"加为联系人"混成一个意思。
      footer={
        <Space>
          <button className="contact-btn" onClick={close} disabled={!!loading}>
            取消
          </button>
          <button className="contact-btn" onClick={onApplyContact} disabled={!!loading}>
            {loading === 'contact' ? '提交中…' : '加为联系人'}
          </button>
          {/* ★★DEV-262：{@code gate === 'no'} = 服务端判过"不是联系人、也不是智能体"
              ⇒ 点了也会被服务端拒（IM_30001）。★这里只禁用**不隐藏**：
              按钮突然消失会让用户以为功能坏了，留着+下面的说明才说得清为什么。 */}
          <button className="contact-btn primary" onClick={onSendChat} disabled={!!loading || gate === 'no'}>
            {loading === 'chat' ? '打开中…' : '发消息'}
          </button>
        </Space>
      }
    >
      <Space direction="vertical" style={{ width: '100%' }}>
        {/* ★两个 Tab：**人** / **智能体**。
            ★用 Tabs 而不是"一个下拉里混着两种东西"：两者的可见范围规则完全不同
            （人 = 平台"可联系人"，智能体 = 该租户内**已发布**的），
            混在一起用户无法判断"为什么我搜不到某个同事/某个智能体"。 */}
        <Tabs
          activeKey={tab}
          onChange={switchTab}
          items={[
            {
              key: 'user',
              // ★DEV-258（用户原话「添加伙伴和添加群员弹框上的"人"文案改为"用户"」）：
              //   同一个改动在 AddMemberModal 也有一处（那边的 tabLabel('用户', n)）。
              label: '用户',
              children: (
                <>
                  <Typography.Text type="secondary">搜索平台用户（只列出"可联系人"）</Typography.Text>
                  {/* ★单选：一次只加一个人。多选下"发消息给谁"这个语义就没法表达了。
                      ★★DEV-202 #217：这里原来有个 mock 分支，渲染写死的
                      {@code MOCK_USER_OPTIONS}（{@code 张三 (9001)} 那一列 Tag）。
                      已删除 —— 见 {@link UserSearchSelect} 类注释（那份名单在平台模式
                      下是错的）与 {@code CreateGroupModal} 里的同一条注释。
                      ⇒ 现在「用户」Tab 两个模式都是同一个搜索框，`value` 仍是 userId。 */}
                  <UserSearchSelect
                    multiple={false}
                    excludeUserIds={[userId]}
                    placeholder="输入用户名或手机号搜索"
                    value={target == null ? [] : [target]}
                    onChange={(v) => {
                      setTarget(v.length ? v[v.length - 1] : null);
                      setTargetIsAgent(false);
                    }}
                  />
                </>
              ),
            },
            {
              key: 'agent',
              label: '智能体',
              children: (
                <>
                  <Typography.Text type="secondary">
                    搜索已发布的智能体（当前租户内你能用到的）
                  </Typography.Text>
                  {/* ★mock 模式也有这个 Tab：mock 的智能体目录是预置的（含一个与真人同号的 9003），
                      它存在的意义正是让"忘了编码"这类串号 bug 在本地就暴露。 */}
                  <AgentSearchSelect
                    value={target == null ? null : String(target)}
                    onChange={(item: AgentSearchItem | null) => {
                      setTarget(item ? item.userId : null);
                      // ★角标只看服务端给的 subjectType（理由见 lib/contact.ts 的 SUBJECT_TYPE）
                      setTargetIsAgent(item?.subjectType === SUBJECT_TYPE.AGENT);
                    }}
                  />
                </>
              ),
            },
          ]}
        />

        {/* ★附言只服务于"加为联系人"这条路：走「发消息」时它不会被发送，
            摆在同一个弹窗里必须说清楚，否则用户写了附言点了发消息，
            会以为对方收到了那句话。
            ★★★DEV-226 需求⑨（用户原话「添加智能体不需要申请附言」）：
            判据从 `!targetIsAgent` 改成 `!agentMode`（= **智能体 Tab 或选中了智能体**）。
            ⇒ 原来在「智能体」Tab 上**还没选人**时（此时 targetIsAgent 仍是 false）
            附言框照样摆在那里 —— 用户点开「智能体」看到的第一眼就是它，
            这正是他要去掉的东西。判据跟着 Tab 走之后，切过去就没有了。 */}
        {!agentMode && (
          <Input.TextArea
            value={applyMsg}
            onChange={(e) => setApplyMsg(e.target.value)}
            placeholder="申请附言（可选，仅「加为联系人」时发送给对方）"
            autoSize={{ minRows: 2, maxRows: 3 }}
            maxLength={100}
            showCount
          />
        )}

        {/* ★★DEV-262：为什么「发消息」是灰的（用户口径：不是联系人一律拒发）。
            ★只有**确定不能发**（gate === 'no'）才显示；'unknown' 时什么都不说
            —— 否则刚选中人的那一瞬间会闪一句"不能发"，而请求其实还没回来。 */}
        {gate === 'no' && (
          <Typography.Text type="warning" style={{ fontSize: 12 }}>
            你们还不是联系人，暂时无法直接发消息。请先「加为联系人」，对方同意后即可发送。
          </Typography.Text>
        )}

        {/* ★提示语用同一个 `agentMode` 而不是 `targetIsAgent`：在智能体 Tab 上
            还没选人时，原来显示的是**人的**那句"对方不会被打扰" ——
            对智能体来说这是错的（它根本不会被打扰，也谈不上"同意"）。 */}
        {agentMode ? (
          <Typography.Text type="secondary" style={{ fontSize: 12 }}>
            「发消息」：立刻建立会话，智能体随后出现在你的智联录里。
            <br />
            「加为联系人」：★<b>直接生效，无需等待</b> —— 智能体不会点「同意」，
            所以服务端对智能体一律按"立刻建立"处理（申请/同意那条路对它永远走不通）。
          </Typography.Text>
        ) : (
          <Typography.Text type="secondary" style={{ fontSize: 12 }}>
            「发消息」：立刻建立会话，他随后出现在你的智联录里（对方不会被打扰）。
            <br />
            「加为联系人」：发一条申请，对方同意后双方互为联系人。
          </Typography.Text>
        )}
      </Space>
    </Modal>
  );
}
