import { useEffect, useState } from 'react';
import { App as AntApp, Checkbox, Input, Modal, Space, Typography } from 'antd';
import { searchApi } from '../api';
import type { ContactSearchItem, ConversationSearchItem, Id, MessageDto } from '../api/types';
import { avatarTone } from '../lib/avatarTone';
// ★DEV-312 ⑦（落点1b）：「转发到…」的最近会话标题与会话列表同一把尺子（备注优先）。
import { remarkOf } from '../lib/contact';
import { convTitleOf } from '../lib/convTitle';
import { UNKNOWN_NAME, formatNameWithAccount } from '../lib/displayName';
import { MAX_FORWARD_ITEMS } from '../lib/forward';
import { useChatStore } from '../store/chat';
import SmartImg from './SmartImg';

/**
 * ★★DEV-305：「转发到…」弹窗 —— 多目标选择器（用户拍板口径③：
 * 最近会话 + 搜人 + 搜群，可一次勾选多个目标），逐条 / 合并两种模式共用。
 *
 * <h2>★为什么是自己画列表，而不是复用 {@code UserSearchSelect}</h2>
 *
 * <p>那个组件只搜<b>人</b>（{@code searchApi.contacts}），而转发目标的一半是
 * <b>会话</b>（群、以及"直接选一个已有单聊"—— 后者不必先知道对方是谁）。
 * 硬塞进去等于给一个 antd Select 重写整个 dropdown；自己画一个行列表反而更小。
 * 但两条既有纪律原样带过来：300ms 防抖 + 清理竞态（{@code UserSearchSelect} 同款），
 * 联系人显示名 {@code formatNameWithAccount(...) || UNKNOWN_NAME}（DEV-202 #218 同款）。
 *
 * <h2>★目标的两种形态与「懒建会话」</h2>
 *
 * <p>勾选的目标分两种：
 * <ul>
 *   <li><b>会话形态</b>（{@code convId} 已知）：最近会话、会话搜索命中、
 *       以及<b>带 {@code p2pConvId} 的联系人</b> —— 提交时直接发；</li>
 *   <li><b>人形态</b>（只有 {@code userId}，还没有单聊会话）：提交时先
 *       {@code store.createP2p}（服务端幂等 + DEV-165 的列表恢复逻辑都在那条路上，
 *       所以走 store 而不是裸调 {@code convApi}）拿到 convId 再发。</li>
 * </ul>
 *
 * <p>★两种形态的 key 在"有 p2pConvId"时<b>故意同形</b>（都是 {@code c:{convId}}）：
 * 同一个人从「联系人」和「会话搜索」两节各点一次，是同一个目标的两次 toggle
 * （第二次是取消）—— 否则会出现"同一个单聊发两遍"的重复转发。
 *
 * <h2>★★提交失败的两段式处置（照 {@code AddMemberModal} 的失败纪律再细分一层）</h2>
 *
 * <ol>
 *   <li><b>建会话阶段失败</b>（createP2p 抛）：还<b>一条消息都没发</b> ⇒
 *       toast + 弹窗不关、已选不清，用户原地重试是安全的；</li>
 *   <li><b>发送阶段失败</b>（forwardMessages 抛）：store 的实现是逐条串行、
 *       失败计数聚合后才抛（「N 条消息转发失败」）⇒ 抛出来时<b>可能已经发出去一部分</b>。
 *       留在原地重试 = 把成功的那部分再发一遍（用户收到重复消息）⇒ toast + <b>关弹窗</b>，
 *       要重发由用户重新勾选（那时他能在会话里看见哪些已经到了）。</li>
 * </ol>
 *
 * <p>★合并模式超过 {@code MAX_FORWARD_ITEMS} 时提交按钮直接禁用 + 顶部说明原因 ——
 * 与 ChatWindow 底部操作栏那道拦截是双保险（两边都拦：操作栏拦"进弹窗之前"，
 * 这里拦"弹窗被别的入口打开"的未来）。
 */

/** 一个已勾选的转发目标（两种形态见类注释）。 */
interface Pick {
  /** 去重键：`c:{convId}` 或 `u:{userId}`。 */
  key: string;
  /** 显示名（toast / 行内文字）。 */
  name: string;
  convId?: Id;
  userId?: Id;
}

export default function ForwardModal({
  open,
  msgs,
  mode,
  title,
  onClose,
  onDone,
}: {
  open: boolean;
  /** ★要转发的消息（勾选顺序）。{@code null} / 空数组时提交按钮禁用（兜底，不该发生）。 */
  msgs: readonly MessageDto[] | null;
  /** ★separate = 逐条转发；merge = 合并成一条「[聊天记录]」。 */
  mode: 'separate' | 'merge';
  /** ★仅 merge 用：卡片标题（ChatWindow 传「xx的聊天记录」）。 */
  title?: string;
  onClose: () => void;
  /** ★提交完成（成功、或发送阶段失败已 toast）后回调：外层借此退出勾选模式。 */
  onDone?: () => void;
}) {
  const userId = useChatStore((s) => s.userId);
  // ★★DEV-322 ②：「最近会话」里的自环行也显示真实姓名（与 ConvList 同口径）。
  const userName = useChatStore((s) => s.userName);
  const convs = useChatStore((s) => s.convs);
  const contacts = useChatStore((s) => s.contacts);
  const createP2p = useChatStore((s) => s.createP2p);
  const forwardMessages = useChatStore((s) => s.forwardMessages);
  const { message: toast } = AntApp.useApp();

  const [picks, setPicks] = useState<Pick[]>([]);
  const [keyword, setKeyword] = useState('');
  const [contactHits, setContactHits] = useState<ContactSearchItem[]>([]);
  const [convHits, setConvHits] = useState<ConversationSearchItem[]>([]);
  const [searching, setSearching] = useState(false);
  /** ★是否搜过：区分"还没输入"和"搜了但没结果"（两种空态文案不同）。 */
  const [searched, setSearched] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  /**
   * ★打开时清空上一次的选择 —— 照 {@code AddMemberModal} 的成例
   * （"渲染期发现变了就重置"，不用 useEffect：effect 要等一帧，
   * 那一帧里旧目标还挂在提交按钮上，手快的用户点下去就发错地方）。
   */
  const [lastOpen, setLastOpen] = useState(open);
  if (open !== lastOpen) {
    setLastOpen(open);
    if (open) {
      setPicks([]);
      setKeyword('');
      setContactHits([]);
      setConvHits([]);
      setSearched(false);
      setSearching(false);
      setSubmitting(false);
    }
  }

  /**
   * ★搜索：300ms 防抖 + 竞态双闸门（清理时 clearTimeout <b>和</b> alive=false）。
   *
   * <p>★两个端点<b>各自 catch</b>：搜人服务降级（{@code degraded}）或搜群挂了，
   * 另一节照常出结果 —— 转发目标是"能选一个是一个"的场景，
   * 一节失败把整个列表清空的连坐没有意义。
   */
  useEffect(() => {
    if (!open) return;
    const kw = keyword.trim();
    if (!kw) {
      setContactHits([]);
      setConvHits([]);
      setSearched(false);
      setSearching(false);
      return;
    }
    let alive = true;
    setSearching(true);
    const timer = setTimeout(() => {
      Promise.all([
        searchApi.contacts(kw, 20).catch(() => ({ items: [] as ContactSearchItem[] })),
        searchApi.conversations(kw, 20).catch(() => [] as ConversationSearchItem[]),
      ])
        .then(([c, g]) => {
          if (!alive) return;
          // ★排除自己：给自己转发在"最近会话"里已经有正经入口（「我自己」），
          //   搜索结果里再出现一次只会在两节里画出两个"自己"。
          const self = userId != null ? String(userId) : '';
          setContactHits((c.items ?? []).filter((x) => String(x.userId) !== self));
          setConvHits(g);
          setSearched(true);
        })
        .finally(() => {
          if (alive) setSearching(false);
        });
    }, 300);
    return () => {
      alive = false;
      clearTimeout(timer);
      setSearching(false);
    };
  }, [open, keyword, userId]);

  const reset = () => {
    setPicks([]);
    setKeyword('');
    setSubmitting(false);
  };

  const close = () => {
    reset();
    onClose();
  };

  const toggle = (p: Pick) => {
    setPicks((prev) => (prev.some((x) => x.key === p.key) ? prev.filter((x) => x.key !== p.key) : [...prev, p]));
  };

  const n = msgs?.length ?? 0;
  const tooMany = mode === 'merge' && n > MAX_FORWARD_ITEMS;

  const onSubmit = async () => {
    if (!msgs || msgs.length === 0 || picks.length === 0 || tooMany) return;
    setSubmitting(true);

    /**
     * ★阶段一：把"人形态"的目标解析成 convId（懒建单聊）。
     * 失败 ⇒ 弹窗不关（此刻还没发出任何消息，原地重试安全，见类注释）。
     */
    const convIds: string[] = [];
    try {
      for (const p of picks) {
        if (p.convId != null) {
          convIds.push(String(p.convId));
          continue;
        }
        const cid = await createP2p(p.userId as Id);
        convIds.push(String(cid));
      }
    } catch (e) {
      toast.error((e as Error).message || '创建单聊失败，请重试');
      setSubmitting(false);
      return;
    }

    /**
     * ★去重：同一个人被"联系人（带 p2pConvId）"与"会话搜索"两节各选一次时 key 已同形，
     * 到不了这里；但 createP2p 返回的可能是<b>已存在</b>的会话 id（服务端幂等），
     * 与另一个 pick 的 convId 撞上 —— 那一行重复会把同一条消息发两遍。
     */
    const uniq = Array.from(new Set(convIds));

    /** ★阶段二：真发送。失败也要关弹窗（可能已发出一部分，见类注释）。 */
    try {
      await forwardMessages(uniq, msgs, mode, mode === 'merge' ? { title } : undefined);
    } catch (e) {
      toast.error((e as Error).message || '转发失败');
      reset();
      onClose();
      onDone?.();
      return;
    } finally {
      setSubmitting(false);
    }

    /**
     * ★以下在 try 之外（{@code AddMemberModal} 同款纪律）：提交已成功，
     * 下面只是"让界面跟上"，混进 try 会把收尾的抖动误报成"转发失败"。
     */
    toast.success(`已转发到 ${uniq.length} 个会话`);
    reset();
    onClose();
    onDone?.();
  };

  /** 最近会话（keyword 为空时的默认列表）：与会话列表同源同序，取前 20。 */
  const recent = keyword.trim() ? [] : convs.slice(0, 20);

  /**
   * ★一行候选目标。
   *
   * <p>★行是 {@code <button>}（键盘可达、语义是"点一下切换勾选"）；
   * 里面的 antd Checkbox 是<b>纯视觉</b>（CSS 把它的 pointer-events 掐掉）——
   * 行的点击是唯一 handler，否则点中 checkbox 会触发两次 toggle（一次抵消，看起来"点不动"）。
   *
   * <p>★头像底色用 {@code avatarTone(name)}（DEV-201 的确定性哈希）：同一个人在
   * 会话列表、这里、搜索结果里是同一个颜色。文字取<b>首个码点</b>（{@code Array.from}，
   * 不用 {@code name[0]} —— 后者遇到 emoji 拿半个代理对，见 avatarTone 同款纪律）。
   * ★群头像在紧凑行里也只画 1 个字（会话列表那种"群名前四字"是给大头像的口径，
   * 32px 的圈里塞 4 个字只会糊成一团）。
   */
  const rowOf = (p: Pick, avatarUrl: string | null | undefined) => {
    const checked = picks.some((x) => x.key === p.key);
    const ch = Array.from(p.name)[0] ?? '?';
    return (
      <button
        type="button"
        key={p.key}
        className={`fwd-pick-row${checked ? ' checked' : ''}`}
        data-fwd-row={p.key}
        onClick={() => toggle(p)}
      >
        <Checkbox checked={checked} className="fwd-pick-box" />
        <span className="fwd-avatar" style={avatarTone(p.name)}>
          {avatarUrl ? (
            /* ★图挂了回落成首字（DEV-249 用户口径「不展示图裂的样子」，SmartImg 是既有实现） */
            <SmartImg
              src={avatarUrl}
              alt=""
              style={{ width: '100%', height: '100%', objectFit: 'cover' }}
              fallback={<>{ch}</>}
            />
          ) : (
            ch
          )}
        </span>
        <span className="fwd-pick-name">{p.name}</span>
      </button>
    );
  };

  return (
    <Modal
      title={mode === 'merge' ? '合并转发' : '转发'}
      open={open}
      onCancel={close}
      destroyOnClose
      footer={
        <Space>
          <button className="contact-btn" onClick={close} disabled={submitting}>
            取消
          </button>
          <button
            className="contact-btn primary"
            data-fwd-submit=""
            onClick={onSubmit}
            disabled={submitting || picks.length === 0 || tooMany || n === 0}
          >
            {submitting ? '转发中…' : picks.length > 0 ? `转发到 ${picks.length} 个会话` : '转发'}
          </button>
        </Space>
      }
    >
      <Space direction="vertical" style={{ width: '100%' }} size={8}>
        <Typography.Text type="secondary" style={{ fontSize: 12 }}>
          {mode === 'merge' ? (
            <>
              已选 <b>{n}</b> 条消息，将合并为一条「[聊天记录]」发送。
            </>
          ) : (
            <>
              已选 <b>{n}</b> 条消息，将按勾选顺序逐条发送。
            </>
          )}
        </Typography.Text>
        {tooMany && (
          <div className="fwd-too-many">
            合并转发一次最多 {MAX_FORWARD_ITEMS} 条（已选 {n} 条），请减少选择或改用逐条转发。
          </div>
        )}
        <Input
          allowClear
          placeholder="搜索联系人或群聊"
          value={keyword}
          onChange={(e) => setKeyword(e.target.value)}
          data-fwd-search=""
        />
        <div className="fwd-pick-list">
          {keyword.trim() ? (
            <>
              {searching && <div className="fwd-pick-empty">搜索中…</div>}
              {!searching && searched && contactHits.length === 0 && convHits.length === 0 && (
                <div className="fwd-pick-empty">未找到相关联系人或会话</div>
              )}
              {contactHits.length > 0 && <div className="fwd-pick-sec">联系人</div>}
              {contactHits.map((c) => {
                const name = formatNameWithAccount(c.nickName, c.userName) || UNKNOWN_NAME;
                // ★有 p2pConvId ⇒ 会话形态（key 与「会话搜索」那节同形，见类注释）
                const p: Pick =
                  c.p2pConvId != null
                    ? { key: `c:${c.p2pConvId}`, name, convId: c.p2pConvId }
                    : { key: `u:${c.userId}`, name, userId: c.userId };
                return rowOf(p, c.avatar);
              })}
              {convHits.length > 0 && <div className="fwd-pick-sec">会话</div>}
              {convHits.map((c) => {
                // ★群没名字兜「群聊{id}」（会话 id 可以上界面，lib/convTitle 同口径）；
                //   P2P 没名字兜「未知用户」（id 不上界面，DEV-202 #218）。
                const name = c.name?.trim() || (c.convType === 1 ? UNKNOWN_NAME : `群聊${c.convId}`);
                return rowOf({ key: `c:${c.convId}`, name, convId: c.convId }, c.avatar);
              })}
            </>
          ) : (
            <>
              <div className="fwd-pick-sec">最近会话</div>
              {recent.length === 0 && (
                <div className="fwd-pick-empty">暂无最近会话，可在上方搜索联系人或群聊</div>
              )}
              {recent.map((c) =>
                rowOf(
                  { key: `c:${c.convId}`, name: convTitleOf(c, userId, remarkOf(contacts, c.peerUserId), userName), convId: c.convId },
                  // ★图源判据与 ConvList 逐字同款：群 = c.avatar、单聊 = c.peerAvatar
                  c.convType === 1 ? c.peerAvatar : c.avatar,
                ),
              )}
            </>
          )}
        </div>
      </Space>
    </Modal>
  );
}
