import { Empty } from 'antd';
import type { TopTabDef } from '../lib/topTabs';

/**
 * ★「后端能力尚未接入」的标签页内容区。
 *
 * <h2>★★它现在没有使用者（DEV-247 起），但【不删】</h2>
 *
 * <p>到 DEV-247 为止，{@code TOP_TABS} 里每一项都接通了（Pin、群公告、「资料库」），
 * 所以 {@code ChatWindow} 那条兜底分支实际上打不开这个组件。留着它的理由是：
 * 这个组件是"用户点名要、但后端还没有能力"时<b>唯一诚实</b>的画法 ——
 * 下一个这样的需求来了，不需要重新发明一遍；而删掉它，下一个人多半会先做一版假数据。
 *
 * <h2>为什么是"摆出来并写明缺什么"，而不是"从菜单里藏起来"</h2>
 *
 * <p>这类标签页都是用户<b>点名要</b>的。藏起来的话，"我勾了怎么没有"会变成一个
 * 只能靠猜的问题（是没做？是没配？是我没找到入口？）；摆出来并写明
 * <b>缺的是哪一块后端能力</b>，用户一眼就知道进度在哪、值不值得等。
 *
 * <p>★这里<b>不做任何假数据、不做本地假存</b>：一个"能点但重启就没了"的置顶，
 * 比一个说清楚"还没做"的空页糟糕得多 —— 前者会让用户以为功能有了，
 * 然后在一个不会生效的地方用它。
 */
export default function ChatPlaceholderPanel({ def }: { def: TopTabDef }) {
  return (
    <div className="chat-panel">
      <div className="chat-panel-head">
        <span className="chat-panel-title">{def.label}</span>
      </div>
      <div className="chat-panel-scroll">
        <Empty
          image={Empty.PRESENTED_IMAGE_SIMPLE}
          style={{ marginTop: 64 }}
          description={
            <div className="panel-pending">
              <div className="panel-pending-title">「{def.label}」还没有接入</div>
              <div className="panel-pending-desc">{def.pending}</div>
              <div className="panel-pending-desc">
                这个标签页是照飞书会话窗口的形态先留出来的<b>入口</b>，功能本身还没做。
                暂时不想看到它，可以从顶部「+ → 管理标签页」去掉。
              </div>
            </div>
          }
        />
      </div>
    </div>
  );
}
