import { useEffect, useState } from 'react';
import { Alert, Avatar, Drawer, Empty, Skeleton, Typography } from 'antd';
import { msgApi } from '../api';
import type { Id, MessageDto } from '../api/types';
import { UNKNOWN_NAME, firstNameOf } from '../lib/displayName';
import { previewTextOf, REPLY_PLACEHOLDER } from '../lib/quote';
import { dividerTime } from '../lib/timeDivider';

/**
 * ★引用链路抽屉（DEV-208）——用户点气泡上的「引用条」时展开<b>完整</b>链路。
 *
 * <h2>★它是一个独立抽屉，<b>不</b>进顶部标签页体系</h2>
 *
 * <p>★这是用户逐字拍板的形态：「点引用弹一个独立右侧抽屉（不进入标签页体系，看完即关）」。
 * 所以本组件<b>不</b>注册到 {@code lib/topTabs.ts}，也不出现在「+ → 管理标签页」里。
 * 「看完即关」不是随手加的：链路是一个<b>问题</b>的答案（"这条引用到底从哪来的"），
 * 回答完就结束了；做成常驻标签页会留下一个多半空着的页。
 *
 * <h2>★每一环都带「跳回原文」，理由与 Pin 面板相同</h2>
 *
 * <p>链路里显示的是<b>摘要</b>，用户看完常常要看原文。没有这个入口的话，
 * 他只能自己往历史里翻 —— 而链上那几环可能间隔几百条消息。
 * ★跳转复用 store 的 {@code focusPinnedMessage}（在内存里就滚、不在就按 seq 拉一页），
 * 在它旁边重复实现一遍"按 seq 补历史"是这轮最容易留下的分叉。
 *
 * <h2>★链路是从「点的那条」向上排的</h2>
 *
 * <p>接口契约写死 {@code data[0]} = 用户点的那条，所以第一环标「本条」，
 * 往下逐级是"它引用的、再引用的……"。★任何一端把这个顺序当成"从根到叶"，
 * 抽屉里画的阶梯就是反的，而<b>有内容</b>这件事会让它看起来是对的。
 */
export default function QuoteChainDrawer({
  convId,
  msgId,
  open,
  onClose,
  /**
   * ★「跳回原文」。★由外层关抽屉并完成定位 —— 关不关、什么时候关是外层的状态，
   * 本组件只负责"用户按了哪一环"。
   */
  onJump,
}: {
  convId: Id | null;
  /**
   * ★链路<b>起点</b>：<b>用户点的那条</b>（即气泡所属的消息本身），<b>不是</b>它引用的那条。
   *
   * <p>与服务端契约逐字对齐（{@code ImMessageApplicationService#listReplyChain}：
   * 「@param msgId 起点消息（就是用户点的那条）」「@return 从起点到根排列」）。
   * ★写成"被引用那条"会让链少一截，而接口照样 200：第一环成了别人发的那条却仍标「本条」。
   */
  msgId: Id | null;
  open: boolean;
  onClose: () => void;
  onJump?: (m: MessageDto) => void;
}) {
  /** null = 还没拉到（加载中）。★不用 [] 当初始值：那会让"加载中"渲染成"链路是空的"。 */
  const [chain, setChain] = useState<MessageDto[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!open || convId == null || msgId == null) return undefined;
    let alive = true;
    setChain(null);
    setError(null);
    msgApi
      .replyChain(msgId, convId)
      .then((rows) => {
        if (alive) setChain(rows ?? []);
      })
      .catch((e: unknown) => {
        // ★失败必须说话：链路拉不到时抽屉里若是空白，用户分不清
        //   "这条消息没有被引用过"与"接口挂了"。
        if (alive) setError((e as Error).message || '引用链路加载失败');
      });
    return () => {
      // ★alive 闸门：快速连点两条引用条时，先发的那个请求可能后到，
      //   不挡的话抽屉里会闪出上一条的链（而且用户已经点了新的那条）。
      alive = false;
    };
  }, [open, convId, msgId]);

  return (
    <Drawer
      title={
        <span>
          引用链路
          {chain && chain.length > 1 ? (
            <Typography.Text type="secondary" style={{ fontSize: 12, fontWeight: 400, marginLeft: 8 }}>
              共 {chain.length} 层
            </Typography.Text>
          ) : null}
        </span>
      }
      open={open}
      onClose={onClose}
      width={400}
    >
      {error != null ? (
        <Alert type="error" showIcon message="引用链路加载失败" description={error} />
      ) : chain == null ? (
        <Skeleton active paragraph={{ rows: 4 }} />
      ) : chain.length === 0 ? (
        // ★服务端对"起点不存在"报的是 IM_20001（会走到上面的 error 分支），
        //   所以这里只可能是畸形响应。留一句话，不留白。
        <Empty description="没有可展开的引用链路" />
      ) : (
        <>
          {/* ★这句话不是装饰：链上出现「引用内容已撤回」时，用户会怀疑链路断了。
              明确告诉他"会继续往上"，否则他会以为功能只展开了一层。 */}
          <div className="quote-chain-hint">
            {`从你点的那条开始逐级向上。标着「${REPLY_PLACEHOLDER}」的那几环，内容已不可见 —— 但链路会继续往上。`}
          </div>
          {chain.map((it, i) => {
            const name = firstNameOf(UNKNOWN_NAME, it.senderName);
            const text = previewTextOf(it);
            return (
              <div className="quote-ring" key={String(it.msgId)}>
                <Avatar
                  size={24}
                  src={it.senderAvatar || undefined}
                  // ★拿不到头像时用中性灰底 + 首字，与顶栏群头像同一套口径
                  //   （不再按 ID 哈希配色：抽屉里的每一环都是"同一条链上的人"，
                  //   彩色反而让人以为颜色有含义）。
                  style={{ background: it.senderAvatar ? undefined : '#c9cdd4', flex: '0 0 auto' }}
                >
                  {name.slice(0, 1)}
                </Avatar>
                <div className="quote-ring-body">
                  <div className="quote-ring-meta">
                    <span className="quote-ring-name">{name}</span>
                    <span className="quote-ring-time">{dividerTime(it.sendTime)}</span>
                    {i === 0 && <span className="quote-ring-here">本条</span>}
                  </div>
                  <div className={`quote-ring-text${text === REPLY_PLACEHOLDER ? ' unavailable' : ''}`}>
                    {text}
                  </div>
                  <button
                    type="button"
                    className="quote-ring-jump"
                    onClick={() => onJump?.(it)}
                    // ★跳过去不可能失败得体面：它要么滚过去，要么（消息已被清理）
                    //   由外层弹 toast。按钮本身不做禁用判断。
                    title="跳到这条消息"
                  >
                    跳回原文
                  </button>
                </div>
              </div>
            );
          })}
        </>
      )}
    </Drawer>
  );
}
